package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMemberLoansUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@Transactional(readOnly = true)
public class GetMemberLoansService implements GetMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;

    public GetMemberLoansService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
    }

    @Override
    public LoanPage getActiveLoans(GetMemberLoansQuery query) {
        loadMemberPort.loadMember(query.memberId()).orElseThrow(() -> new MemberNotFoundException(query.memberId()));
        List<Loan> loans = loadLoanPort.loadActiveLoansByMemberId(query.memberId(), query.page(), query.size());
        Map<UUID, String> titles = loadTitles(loans);
        List<ActiveLoan> items = loans.stream()
                .map(loan -> new ActiveLoan(loan.getId(), loan.getBookId(), titles.get(loan.getBookId()),
                        loan.getLoanedAt(), loan.getDueAt()))
                .toList();
        long totalCount = loadLoanPort.countActiveLoansByMemberId(query.memberId());
        return new LoanPage(items, query.page(), query.size(), totalCount);
    }

    @Override
    public List<LoanHistory> getLoanHistory(UUID memberId) {
        loadMemberPort.loadMember(memberId).orElseThrow(() -> new MemberNotFoundException(memberId));
        List<Loan> loans = loadLoanPort.loadLoansByMemberId(memberId);
        Map<UUID, String> titles = loadTitles(loans);
        return loans.stream()
                .map(loan -> new LoanHistory(loan.getId(), titles.get(loan.getBookId()), loan.getLoanedAt(),
                        loan.getReturnedAt(), loan.isReturned() ? loan.lateFee() : null))
                .toList();
    }

    private Map<UUID, String> loadTitles(List<Loan> loans) {
        List<UUID> bookIds = loans.stream().map(Loan::getBookId).toList();
        Map<UUID, String> titles = loadBookPort.loadBooks(bookIds).stream()
                .collect(Collectors.toMap(Book::getId, Book::getTitle));
        for (UUID bookId : bookIds) {
            if (!titles.containsKey(bookId)) {
                throw new BookNotFoundException(bookId);
            }
        }
        return titles;
    }
}
