package com.example.lending.application.port.in;

import java.time.Year;

public interface GetMonthlyStatsUseCase {

    MonthlyStats getMonthlyStats(GetMonthlyStatsQuery query);

    record GetMonthlyStatsQuery(int year, int month) {

        public GetMonthlyStatsQuery {
            if (year < Year.MIN_VALUE || year > Year.MAX_VALUE) {
                throw new IllegalArgumentException("year is out of range");
            }
            if (month < 1 || month > 12) {
                throw new IllegalArgumentException("month must be between 1 and 12");
            }
        }
    }

    /**
     * 대출일이 해당 달인 대출 수({@code loanCount}), 반납일이 해당 달인 반납 수({@code returnCount}),
     * 반납일이 해당 달이고 연체료가 0보다 큰 반납 수({@code overdueCount}), 그 반납들의 연체료 합계({@code lateFeeTotal}).
     */
    record MonthlyStats(int year, int month, long loanCount, long returnCount, long overdueCount,
                        long lateFeeTotal) {
    }
}

