package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadLoanPort loadLoanPort;

    public GetMonthlyStatsService(LoadLoanPort loadLoanPort) {
        this.loadLoanPort = loadLoanPort;
    }

    @Override
    public MonthlyStats getMonthlyStats(GetMonthlyStatsQuery query) {
        YearMonth yearMonth = YearMonth.of(query.year(), query.month());
        LocalDate from = yearMonth.atDay(1);
        LocalDate to = yearMonth.atEndOfMonth();

        long loanCount = loadLoanPort.loadLoansLoanedBetween(from, to).size();
        List<Loan> returned = loadLoanPort.loadLoansReturnedBetween(from, to);
        List<Long> lateFees = returned.stream().map(Loan::lateFee).toList();
        long overdueCount = lateFees.stream().filter(fee -> fee > 0).count();
        long lateFeeTotal = lateFees.stream().mapToLong(Long::longValue).sum();

        return new MonthlyStats(query.year(), query.month(), loanCount, returned.size(), overdueCount, lateFeeTotal);
    }
}

