package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// 테스트 간 공유되는 DB에서 다른 테스트의 데이터와 섞이지 않도록 각 테스트가 서로 다른 달(2031년)을 쓴다.
@SpringBootTest
@AutoConfigureMockMvc
class MonthlyStatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void late_return_counts_as_return_and_overdue_in_return_month_and_loan_in_loan_month() throws Exception {
        String memberId = registerMember();
        String loanId = loanBook(registerBook(), memberId, "2031-05-03");
        // 대출 기간 14일: 기한 2031-05-17 이후 06-10 반납이면 24일 연체 → 2400
        returnBook(loanId, "2031-06-10");

        mockMvc.perform(get("/stats/monthly").param("year", "2031").param("month", "5"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2031))
                .andExpect(jsonPath("$.month").value(5))
                .andExpect(jsonPath("$.loanCount").value(1))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));

        mockMvc.perform(get("/stats/monthly").param("year", "2031").param("month", "6"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(1))
                .andExpect(jsonPath("$.overdueCount").value(1))
                .andExpect(jsonPath("$.lateFeeTotal").value(2400));
    }

    @Test
    void on_time_return_is_counted_without_overdue_or_fee() throws Exception {
        String memberId = registerMember();
        String loanId = loanBook(registerBook(), memberId, "2031-09-01");
        returnBook(loanId, "2031-09-10");

        mockMvc.perform(get("/stats/monthly").param("year", "2031").param("month", "9"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(1))
